def leading_minority_count(row, minority_val):
    """Count how many consecutive minority values are at the start of the row"""
    count = 0
    for val in row:
        if val == minority_val:
            count += 1
        else:
            break
    return count

def trailing_majority_count(row, majority_val):
    """Count how many consecutive majority values are at the end of the row"""
    count = 0
    for val in reversed(row):
        if val == majority_val:
            count += 1
        else:
            break
    return count

