def run_info(row):
    runs = []
    if not row:
        return runs

    current_val = row[0]
    start = 0
    length = 0

    for val in row:
        if val == current_val:
            length += 1
        else:
            if length > 0:
                runs.append((current_val, start, length))
            current_val = val
            start = len(row) - length  
            length = 1

